// =========================================================================
// CELEBRATION KITTEN VIDEO, REALISTIC BALLOON POP & GSAP RTL TIMELINE
// =========================================================================
(function() {
  'use strict';

  // 1. Web Audio Synthesizer for Realistic Balloon Pop
  let audioCtx = null;
  function getAudioCtx() {
    if (!audioCtx) {
      const AudioContextClass = window.AudioContext || window.webkitAudioContext;
      if (AudioContextClass) audioCtx = new AudioContextClass();
    }
    if (audioCtx && audioCtx.state === 'suspended') {
      audioCtx.resume().catch(function() {});
    }
    return audioCtx;
  }

  function playBalloonPopSound() {
    try {
      const ctx = getAudioCtx();
      if (!ctx) return;
      const now = ctx.currentTime;

      // Quick pitch-down pop impulse
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'triangle';
      osc.frequency.setValueAtTime(540, now);
      osc.frequency.exponentialRampToValueAtTime(45, now + 0.08);

      gain.gain.setValueAtTime(0.35, now);
      gain.gain.exponentialRampToValueAtTime(0.001, now + 0.08);

      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start(now);
      osc.stop(now + 0.09);

      // Noise burst for rubber snap
      const bufferSize = ctx.sampleRate * 0.06;
      const buffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
      const data = buffer.getChannelData(0);
      for (let i = 0; i < bufferSize; i++) {
        data[i] = (Math.random() * 2 - 1) * Math.exp(-i / (bufferSize * 0.25));
      }
      const noise = ctx.createBufferSource();
      noise.buffer = buffer;
      const noiseFilter = ctx.createBiquadFilter();
      noiseFilter.type = 'highpass';
      noiseFilter.frequency.setValueAtTime(800, now);
      const noiseGain = ctx.createGain();
      noiseGain.gain.setValueAtTime(0.25, now);
      noiseGain.gain.exponentialRampToValueAtTime(0.001, now + 0.06);

      noise.connect(noiseFilter);
      noiseFilter.connect(noiseGain);
      noiseGain.connect(ctx.destination);
      noise.start(now);
    } catch (e) {
      // Audio playback fails silently if unsupported
    }
  }

  // Realistic Balloon Pop Burst Particles
  function createBalloonPopParticles(x, y, balloonColor) {
    const container = document.getElementById('om-bday-balloon-field') || document.body;
    const count = 16;
    for (let i = 0; i < count; i++) {
      const p = document.createElement('span');
      p.className = 'om-bday-pop-particle';
      const angle = (i / count) * Math.PI * 2 + (Math.random() * 0.4 - 0.2);
      const dist = 45 + Math.random() * 75;
      const tx = Math.cos(angle) * dist;
      const ty = Math.sin(angle) * dist + 15;
      const size = 5 + Math.random() * 7;
      const isGlitter = i % 2 === 0;

      p.style.cssText = 'position: absolute;' +
        'left:' + x + 'px;' +
        'top:' + y + 'px;' +
        'width:' + size + 'px;' +
        'height:' + (size * (isGlitter ? 1 : 1.4)) + 'px;' +
        'border-radius:' + (isGlitter ? '50%' : '3px 6px 4px 6px') + ';' +
        'background:' + (isGlitter ? '#fff8db' : (balloonColor || '#ff8ea3')) + ';' +
        'box-shadow:0 0 6px ' + (isGlitter ? '#ffd29e' : 'rgba(0,0,0,0.2)') + ';' +
        'pointer-events:none;' +
        'z-index:9999;' +
        'transform:translate(-50%, -50%) scale(1);' +
        'transition:transform 0.65s cubic-bezier(0.12, 0.8, 0.32, 1), opacity 0.65s ease;' +
        'opacity:1;';
      container.appendChild(p);

      requestAnimationFrame(function() {
        p.style.transform = 'translate(calc(-50% + ' + tx + 'px), calc(-50% + ' + ty + 'px)) rotate(' + (Math.random() * 360) + 'deg) scale(' + (Math.random() * 0.5) + ')';
        p.style.opacity = '0';
      });

      setTimeout(function() {
        if (p.parentNode) p.parentNode.removeChild(p);
      }, 700);
    }
  }

  // Intercept Balloon clicks to attach realistic pop effect & sound
  function setupBalloonPop() {
    const field = document.getElementById('om-bday-balloon-field');
    if (!field || field.dataset.popReady === 'true') return;
    field.dataset.popReady = 'true';

    field.addEventListener('click', function(e) {
      const balloon = e.target.closest('.om-bday-balloon');
      if (!balloon || balloon.classList.contains('is-popped')) return;

      const rect = balloon.getBoundingClientRect();
      const fieldRect = field.getBoundingClientRect();
      const x = rect.left + rect.width / 2 - fieldRect.left;
      const y = rect.top + rect.height / 2 - fieldRect.top;
      const color = window.getComputedStyle(balloon).backgroundColor || '#ff7a59';

      playBalloonPopSound();
      createBalloonPopParticles(x, y, color);
    }, true);
  }

  // 2. Celebration Kitten Video Controller
  function setupKittenVideo() {
    const vid = document.getElementById('om-bday-vid');
    const vidScene = document.getElementById('om-bday-scene-video');
    const playToggleBtn = document.getElementById('om-bday-vid-play-toggle');
    const skipBtn1 = document.getElementById('om-bday-vid-skip-btn');
    const skipBtn2 = document.getElementById('om-bday-vid-skip');
    const tapOverlay = document.getElementById('om-bday-vid-tap');
    const soundBtn = document.getElementById('om-bday-vid-sound');
    const waitSpinner = document.getElementById('om-bday-vid-wait');
    const progressBar = document.getElementById('om-bday-vid-bar');

    if (!vid || !vidScene) return;

    function advanceToMemories() {
      try {
        vid.pause();
      } catch (e) {}
      if (skipBtn2) {
        skipBtn2.click();
      }
    }

    if (!vid.src || !vid.src.includes('bday-wish.mp4')) {
      vid.src = 'images/bday-wish.mp4';
      vid.load();
    }

    if (waitSpinner) {
      vid.addEventListener('canplay', function() {
        waitSpinner.classList.remove('is-shown');
      });
    }

    vid.addEventListener('timeupdate', function() {
      if (progressBar && vid.duration && isFinite(vid.duration)) {
        const pct = Math.min(1, vid.currentTime / vid.duration);
        progressBar.style.transform = 'scaleX(' + pct.toFixed(4) + ')';
      }
    });

    vid.addEventListener('ended', function() {
      advanceToMemories();
    });

    if (skipBtn1 && !skipBtn1.dataset.wired) {
      skipBtn1.dataset.wired = 'true';
      skipBtn1.addEventListener('click', function(e) {
        e.stopPropagation();
        advanceToMemories();
      });
    }

    if (playToggleBtn && !playToggleBtn.dataset.wired) {
      playToggleBtn.dataset.wired = 'true';
      playToggleBtn.addEventListener('click', function(e) {
        e.stopPropagation();
        if (vid.paused) {
          vid.muted = false;
          vid.play().then(function() {
            playToggleBtn.textContent = '⏸ Pause';
            if (soundBtn) soundBtn.classList.remove('is-shown');
            if (tapOverlay) tapOverlay.classList.remove('is-shown');
          }).catch(function() {
            vid.muted = true;
            vid.play().then(function() {
              playToggleBtn.textContent = '⏸ Pause';
              if (soundBtn) soundBtn.classList.add('is-shown');
            });
          });
        } else {
          vid.pause();
          playToggleBtn.textContent = '▶ Play Video';
        }
      });
    }

    vid.addEventListener('play', function() {
      if (playToggleBtn) playToggleBtn.textContent = '⏸ Pause';
      if (tapOverlay) tapOverlay.classList.remove('is-shown');
      if (waitSpinner) waitSpinner.classList.remove('is-shown');
    });

    vid.addEventListener('pause', function() {
      if (playToggleBtn) playToggleBtn.textContent = '▶ Play Video';
    });

    if (vidScene.classList.contains('is-active')) {
      if (skipBtn2) skipBtn2.classList.add('is-shown');
      
      const playPromise = vid.play();
      if (playPromise !== undefined) {
        playPromise.then(function() {
          if (playToggleBtn) playToggleBtn.textContent = '⏸ Pause';
          if (waitSpinner) waitSpinner.classList.remove('is-shown');
          if (tapOverlay) tapOverlay.classList.remove('is-shown');
        }).catch(function() {
          vid.muted = true;
          vid.play().then(function() {
            if (playToggleBtn) playToggleBtn.textContent = '⏸ Pause';
            if (soundBtn) soundBtn.classList.add('is-shown');
          }).catch(function() {
            if (tapOverlay) tapOverlay.classList.add('is-shown');
          });
        });
      }
    }
  }

  // 3. Right-to-Left Swapping Memory Timeline Engine with GSAP Entrance
  const MEMORY_DATA = [
    {
      url: 'https://i.ibb.co/vCpfvrNH/Snapchat-2135142318.jpg',
      fallback: 'images/shweta-memory-1.jpg',
      aspect: 'auto'
    },
    {
      url: 'https://i.ibb.co/HTDBqz2T/Canva-download.jpg',
      fallback: 'images/shweta-memory-2.png',
      aspect: 'auto'
    },
    {
      url: 'https://i.ibb.co/Tx1Lzj3L/file-00000000a5a0821183d89d52802c657e.png',
      fallback: 'images/shweta-memory-3.jpg',
      aspect: 'auto'
    },
    {
      url: 'https://i.ibb.co/nMDFwJ0d/memory-portrait-snapchat-3.jpg',
      fallback: 'images/shweta-memory-4.png',
      aspect: 'auto'
    },
    {
      url: 'https://i.ibb.co/8nfHNBQP/Snapchat-1599886198.jpg',
      fallback: 'images/shweta-memory-5.jpg',
      aspect: 'auto'
    }
  ];

  let currentMemIdx = 0;
  function setupMemoryTimeline() {
    const memScene = document.getElementById('om-bday-scene-memories');
    const track = document.getElementById('om-bday-photo-string');
    const prevBtn = document.getElementById('om-bday-timeline-prev');
    const nextBtn = document.getElementById('om-bday-timeline-next');
    const dotsWrap = document.getElementById('om-bday-mem-dots');
    if (!memScene || !track) return;

    const cards = Array.from(track.querySelectorAll('.om-bday-photo-frame'));
    if (!cards.length) return;

    // Use runtime OM_BIRTHDAY_DATA if available, otherwise MEMORY_DATA
    const runtimePhotos = (window.OM_BIRTHDAY_DATA && Array.isArray(window.OM_BIRTHDAY_DATA.p) && window.OM_BIRTHDAY_DATA.p.length) 
      ? window.OM_BIRTHDAY_DATA.p 
      : null;

    cards.forEach(function(card, idx) {
      const fallbackInfo = MEMORY_DATA[idx % MEMORY_DATA.length];
      const targetUrl = (runtimePhotos && runtimePhotos[idx]) ? runtimePhotos[idx] : fallbackInfo.url;
      const img = card.querySelector('img');
      const caption = card.querySelector('.om-bday-photo-caption, .om-bday-photo-cap');
      
      if (caption) caption.textContent = '';

      if (img) {
        img.src = targetUrl;
        img.onerror = function() {
          img.src = fallbackInfo.fallback;
        };

        const updateOrientation = function() {
          if (img.naturalWidth && img.naturalHeight) {
            if (img.naturalWidth > img.naturalHeight * 1.1) {
              card.classList.add('is-landscape');
              card.classList.remove('is-portrait');
            } else {
              card.classList.add('is-portrait');
              card.classList.remove('is-landscape');
            }
          }
        };

        img.onload = updateOrientation;
        if (img.complete && img.naturalWidth) {
          updateOrientation();
        }
      }
    });

    // GSAP Entrance Animation for each memory photo as it enters viewport
    if (window.gsap && memScene.classList.contains('is-active') && !track.dataset.gsapAnimated) {
      track.dataset.gsapAnimated = 'true';
      window.gsap.fromTo(cards, 
        { 
          opacity: 0, 
          y: 45, 
          scale: 0.90,
          rotation: function(i) { return (i % 2 === 0 ? -3 : 3); }
        }, 
        { 
          opacity: 1, 
          y: 0, 
          scale: 1, 
          rotation: 0,
          duration: 0.8, 
          stagger: 0.14, 
          ease: 'back.out(1.2)' 
        }
      );
    }

    function scrollToCard(index) {
      if (index < 0) index = 0;
      if (index >= cards.length) index = cards.length - 1;
      currentMemIdx = index;
      
      const targetCard = cards[index];
      if (targetCard) {
        targetCard.scrollIntoView({ behavior: 'smooth', inline: 'center', block: 'nearest' });
      }

      if (dotsWrap) {
        const dots = dotsWrap.querySelectorAll('.om-bday-mem-dot');
        dots.forEach(function(d, i) {
          d.classList.toggle('is-current', i === index);
        });
      }

      if (window.gsap && cards[index]) {
        window.gsap.fromTo(cards[index], 
          { scale: 0.96 }, 
          { scale: 1, duration: 0.4, ease: 'power2.out' }
        );
      }
    }

    if (prevBtn && !prevBtn.dataset.wired) {
      prevBtn.dataset.wired = 'true';
      prevBtn.addEventListener('click', function(e) {
        e.stopPropagation();
        scrollToCard(currentMemIdx - 1);
      });
    }

    if (nextBtn && !nextBtn.dataset.wired) {
      nextBtn.dataset.wired = 'true';
      nextBtn.addEventListener('click', function(e) {
        e.stopPropagation();
        scrollToCard(currentMemIdx + 1);
      });
    }
  }

  // Scene Observer
  const sceneObserver = new MutationObserver(function() {
    const balScene = document.getElementById('om-bday-scene-balloons');
    if (balScene && balScene.classList.contains('is-active')) {
      setupBalloonPop();
    }

    const vidScene = document.getElementById('om-bday-scene-video');
    if (vidScene && vidScene.classList.contains('is-active')) {
      setupKittenVideo();
    }

    const memScene = document.getElementById('om-bday-scene-memories');
    if (memScene && memScene.classList.contains('is-active')) {
      setupMemoryTimeline();
    }
  });

  function init() {
    const stage = document.getElementById('om-bday-stage') || document.body;
    if (stage) {
      sceneObserver.observe(stage, { attributes: true, subtree: true, attributeFilter: ['class'] });
    }
    setupBalloonPop();
    setupKittenVideo();
    setupMemoryTimeline();
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
